(() => {
  'use strict';

  const PAGE_W = 595.28;
  const PAGE_H = 841.89;
  const MARGIN_X = 34.02;
  const CONTENT_W = PAGE_W - (MARGIN_X * 2);
  const COLORS = {
    navy: '#0c2856', blue: '#1267f1', purple: '#4823d7', lightBlue: '#edf5ff',
    lightPurple: '#f5f2ff', green: '#059669', lightGreen: '#f0fdf4', greenBorder: '#bde8cf', gray900: '#1f2937', gray700: '#4b5563', gray500: '#6b7280',
    gray200: '#e5e7eb', white: '#ffffff', row: '#fafbfc'
  };
  const SYMBOLS = { BDT: 'BDT ', USD: '$', EUR: 'EUR ', GBP: 'GBP ' };
  const DEFAULT_NOTES = 'Electronic products are supplied with the applicable manufacturer or supplier warranty. Warranty excludes misuse, liquid damage, power surges, unauthorised repair, and normal wear. Rental items remain Scifer property; the customer is responsible for safe use, loss, theft, damage, late return, and related charges. Services, installation, and support are limited to the agreed scope; approved extra work and materials are billed separately. Returns require prior approval and inspection. Payment is due upon receipt unless agreed otherwise in writing.';
  const ICON_JPEG_B64 = '';
  const TEXT_JPEG_B64 = '';
  const WATERMARK_JPEG_B64 = '';

  function hexRgb(hex) {
    const value = hex.replace('#', '');
    const r = parseInt(value.slice(0, 2), 16) / 255;
    const g = parseInt(value.slice(2, 4), 16) / 255;
    const b = parseInt(value.slice(4, 6), 16) / 255;
    return `${r.toFixed(3)} ${g.toFixed(3)} ${b.toFixed(3)}`;
  }

  function pdfEscape(value) {
    return String(value ?? '')
      .normalize('NFKD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^\x20-\x7E]/g, '?')
      .replace(/\\/g, '\\\\')
      .replace(/\(/g, '\\(')
      .replace(/\)/g, '\\)');
  }

  // Base-14 Helvetica glyph widths (1/1000 em). These make right-aligned PDF
  // labels line up with the actual rendered glyph edge, unlike a character-count estimate.
  const HELVETICA_WIDTHS = {
    normal: {
      ' ': 278, '!': 278, '"': 355, '#': 556, '$': 556, '%': 889, '&': 667, "'": 191, '(': 333, ')': 333,
      '*': 389, '+': 584, ',': 278, '-': 333, '.': 278, '/': 278, '0': 556, '1': 556, '2': 556, '3': 556,
      '4': 556, '5': 556, '6': 556, '7': 556, '8': 556, '9': 556, ':': 278, ';': 278, '<': 584, '=': 584,
      '>': 584, '?': 556, '@': 1015, 'A': 667, 'B': 667, 'C': 722, 'D': 722, 'E': 667, 'F': 611, 'G': 778,
      'H': 722, 'I': 278, 'J': 500, 'K': 667, 'L': 556, 'M': 833, 'N': 722, 'O': 778, 'P': 667, 'Q': 778,
      'R': 722, 'S': 667, 'T': 611, 'U': 722, 'V': 667, 'W': 944, 'X': 667, 'Y': 667, 'Z': 611, '[': 278,
      '\\': 278, ']': 278, '^': 469, '_': 556, '`': 333, 'a': 556, 'b': 556, 'c': 500, 'd': 556, 'e': 556,
      'f': 278, 'g': 556, 'h': 556, 'i': 222, 'j': 222, 'k': 500, 'l': 222, 'm': 833, 'n': 556, 'o': 556,
      'p': 556, 'q': 556, 'r': 333, 's': 500, 't': 278, 'u': 556, 'v': 500, 'w': 722, 'x': 500, 'y': 500,
      'z': 500, '{': 334, '|': 260, '}': 334, '~': 584
    },
    bold: {
      ' ': 278, '!': 333, '"': 474, '#': 556, '$': 556, '%': 889, '&': 722, "'": 278, '(': 333, ')': 333,
      '*': 389, '+': 584, ',': 278, '-': 333, '.': 278, '/': 278, '0': 556, '1': 556, '2': 556, '3': 556,
      '4': 556, '5': 556, '6': 556, '7': 556, '8': 556, '9': 556, ':': 333, ';': 333, '<': 584, '=': 584,
      '>': 584, '?': 611, '@': 975, 'A': 722, 'B': 722, 'C': 722, 'D': 722, 'E': 667, 'F': 611, 'G': 778,
      'H': 722, 'I': 278, 'J': 556, 'K': 722, 'L': 611, 'M': 833, 'N': 722, 'O': 778, 'P': 667, 'Q': 778,
      'R': 722, 'S': 667, 'T': 611, 'U': 722, 'V': 667, 'W': 944, 'X': 667, 'Y': 611, 'Z': 611, '[': 333,
      '\\': 278, ']': 333, '^': 584, '_': 556, '`': 333, 'a': 556, 'b': 611, 'c': 556, 'd': 611, 'e': 556,
      'f': 333, 'g': 611, 'h': 611, 'i': 278, 'j': 278, 'k': 556, 'l': 278, 'm': 889, 'n': 611, 'o': 611,
      'p': 611, 'q': 611, 'r': 389, 's': 556, 't': 333, 'u': 611, 'v': 556, 'w': 778, 'x': 556, 'y': 556,
      'z': 500, '{': 389, '|': 280, '}': 389, '~': 584
    }
  };

  function textWidth(text, size, bold = false) {
    const metrics = bold ? HELVETICA_WIDTHS.bold : HELVETICA_WIDTHS.normal;
    let units = 0;
    for (const character of String(text ?? '')) units += metrics[character] || 556;
    return (units / 1000) * size;
  }

  function dateLabel(value) {
    if (!value) return '[DD MMM YYYY]';
    const parts = value.split('-').map(Number);
    if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) return '[DD MMM YYYY]';
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${String(parts[2]).padStart(2, '0')} ${months[parts[1] - 1]} ${parts[0]}`;
  }

  function field(value, fallback) {
    return value && String(value).trim() ? String(value).trim() : fallback;
  }

  function numberOrZero(value) {
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
  }

  function itemHasContent(item) {
    return Boolean(
      String(item?.description || '').trim()
      || String(item?.quantity || '').trim()
      || String(item?.unitPrice || '').trim()
    );
  }

  function getPrintableItems(items) {
    const populated = (Array.isArray(items) ? items : []).filter(itemHasContent).slice(0, 10);
    return populated.length ? populated : [{ description: '', quantity: '', unitPrice: '' }];
  }

  function money(value, currency) {
    const prefix = SYMBOLS[currency] || `${currency} `;
    const number = Number.isFinite(value) ? value : 0;
    return `${prefix}${number.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }

  function totals(draft) {
    const fields = draft.fields || {};
    const items = Array.isArray(draft.items) ? draft.items : [];
    const subtotal = items.reduce((sum, item) => sum + numberOrZero(item.quantity) * numberOrZero(item.unitPrice), 0);
    const discount = Math.min(numberOrZero(fields.discount), subtotal);
    const taxable = Math.max(0, subtotal - discount);
    const tax = taxable * (numberOrZero(fields.taxRate) / 100);
    const total = taxable + tax;
    const requestedPaid = fields.paymentStatus === 'paid' ? total : numberOrZero(fields.paidAmount);
    const paid = Math.min(requestedPaid, total);
    const balance = Math.max(0, total - paid);
    return { subtotal, discount, tax, total, paid, balance };
  }

  function wrapText(input, maxWidth, size, bold = false) {
    const text = String(input || '');
    if (!text) return [''];
    const rawWords = text.split(/\s+/);
    const lines = [];
    let current = '';
    rawWords.forEach((word) => {
      const candidate = current ? `${current} ${word}` : word;
      if (textWidth(candidate, size, bold) <= maxWidth || !current) {
        current = candidate;
      } else {
        lines.push(current);
        current = word;
      }
    });
    if (current) lines.push(current);
    return lines;
  }

  function b64ToBytes(base64) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return bytes;
  }

  function ascii(value) {
    return new TextEncoder().encode(value);
  }

  function concatBytes(parts) {
    const length = parts.reduce((sum, part) => sum + part.length, 0);
    const output = new Uint8Array(length);
    let offset = 0;
    parts.forEach((part) => { output.set(part, offset); offset += part.length; });
    return output;
  }

  function makePdf(content) {
    const icon = b64ToBytes(ICON_JPEG_B64);
    const wordmark = b64ToBytes(TEXT_JPEG_B64);
    const watermark = b64ToBytes(WATERMARK_JPEG_B64);
    const stream = ascii(content);
    const objects = [
      null,
      ascii('<< /Type /Catalog /Pages 2 0 R >>'),
      ascii('<< /Type /Pages /Kids [3 0 R] /Count 1 >>'),
      ascii('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /ProcSet [/PDF /Text /ImageC] /Font << /F1 5 0 R /F2 6 0 R >> /XObject << /Im1 7 0 R /Im2 8 0 R /Im3 9 0 R >> >> /Contents 4 0 R >>'),
      concatBytes([ascii(`<< /Length ${stream.length} >>\nstream\n`), stream, ascii('\nendstream')]),
      ascii('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>'),
      ascii('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'),
      concatBytes([ascii(`<< /Type /XObject /Subtype /Image /Width 686 /Height 845 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${icon.length} >>\nstream\n`), icon, ascii('\nendstream')]),
      concatBytes([ascii(`<< /Type /XObject /Subtype /Image /Width 1654 /Height 334 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${wordmark.length} >>\nstream\n`), wordmark, ascii('\nendstream')]),
      concatBytes([ascii(`<< /Type /XObject /Subtype /Image /Width 586 /Height 745 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${watermark.length} >>\nstream\n`), watermark, ascii('\nendstream')]),
    ];

    const header = ascii('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
    const renderedObjects = [];
    const offsets = new Array(objects.length).fill(0);
    let offset = header.length;
    for (let index = 1; index < objects.length; index += 1) {
      const object = concatBytes([ascii(`${index} 0 obj\n`), objects[index], ascii('\nendobj\n')]);
      offsets[index] = offset;
      offset += object.length;
      renderedObjects.push(object);
    }
    const xrefOffset = offset;
    let xref = `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
    for (let index = 1; index < objects.length; index += 1) xref += `${String(offsets[index]).padStart(10, '0')} 00000 n \n`;
    const trailer = `${xref}trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
    return concatBytes([header, ...renderedObjects, ascii(trailer)]);
  }

  function buildContent(draft) {
    const fields = draft.fields || {};
    const items = Array.isArray(draft.items) ? draft.items : [];
    const currency = fields.currency || 'BDT';
    const valueTotals = totals(draft);
    const commands = [];
    const y = (top, height = 0) => PAGE_H - top - height;

    function fill(hex) { commands.push(`${hexRgb(hex)} rg`); }
    function stroke(hex) { commands.push(`${hexRgb(hex)} RG`); }
    function rect(x, top, width, height, options = {}) {
      const { fillColor, strokeColor, lineWidth = 0.5 } = options;
      if (fillColor) fill(fillColor);
      if (strokeColor) { stroke(strokeColor); commands.push(`${lineWidth} w`); }
      commands.push(`${x.toFixed(2)} ${y(top, height).toFixed(2)} ${width.toFixed(2)} ${height.toFixed(2)} re ${fillColor && strokeColor ? 'B' : fillColor ? 'f' : 'S'}`);
    }
    function line(x1, top1, x2, top2, color, width = 0.5) {
      stroke(color);
      commands.push(`${width} w ${x1.toFixed(2)} ${y(top1).toFixed(2)} m ${x2.toFixed(2)} ${y(top2).toFixed(2)} l S`);
    }
    function image(name, x, top, width, height) {
      commands.push(`q ${width.toFixed(2)} 0 0 ${height.toFixed(2)} ${x.toFixed(2)} ${y(top, height).toFixed(2)} cm /${name} Do Q`);
    }
    function text(value, x, top, size = 10, color = COLORS.gray900, bold = false, align = 'left') {
      const safe = pdfEscape(value);
      const width = textWidth(safe, size, bold);
      let actualX = x;
      if (align === 'right') actualX = x - width;
      if (align === 'center') actualX = x - (width / 2);
      fill(color);
      commands.push(`BT /${bold ? 'F2' : 'F1'} ${size.toFixed(2)} Tf 1 0 0 1 ${actualX.toFixed(2)} ${(PAGE_H - top - (size * 0.80)).toFixed(2)} Tm (${safe}) Tj ET`);
    }
    function multilines(value, x, top, width, size, color, maxLines = 2, bold = false) {
      const lines = wrapText(value, width, size, bold).slice(0, maxLines);
      lines.forEach((entry, index) => text(entry, x, top + (index * (size + 1.8)), size, color, bold));
      return lines.length;
    }

    // Watermark
    image('Im3', 128, 205, 340, 417);

    // Header
    image('Im1', MARGIN_X, 23, 27.5, 33.8);
    image('Im2', MARGIN_X + 34, 28, 140, 28.3);
    text('Future-Ready Tech Solutions', MARGIN_X, 64, 6.7, COLORS.navy);
    text('INVOICE', PAGE_W - MARGIN_X, 31, 25, COLORS.blue, true, 'right');
    text('Professional Services & Technology Solutions', PAGE_W - MARGIN_X, 61, 6.4, COLORS.gray500, false, 'right');
    rect(MARGIN_X, 84, CONTENT_W, 2.3, { fillColor: COLORS.blue });

    // Single customer address and two-line invoice details panel.
    const topBoxY = 101;
    const topBoxH = 71;
    const leftW = CONTENT_W * 0.55;
    const rightW = CONTENT_W - leftW;
    rect(MARGIN_X, topBoxY, leftW, topBoxH, { fillColor: COLORS.white, strokeColor: COLORS.gray200 });
    rect(MARGIN_X, topBoxY, leftW, 2, { fillColor: COLORS.blue });
    rect(MARGIN_X + leftW, topBoxY, rightW, topBoxH, { fillColor: COLORS.lightBlue, strokeColor: COLORS.gray200 });
    rect(MARGIN_X + leftW, topBoxY, rightW, 2, { fillColor: COLORS.purple });
    text('BILL TO', MARGIN_X + 10, topBoxY + 10, 8.2, COLORS.blue, true);
    text(field(fields.customerName, '[Customer / Company Name]'), MARGIN_X + 10, topBoxY + 24, 10.1, fields.customerName ? COLORS.gray900 : '#94a3b8', true);
    text(field(fields.customerAddress, '[Customer address]'), MARGIN_X + 10, topBoxY + 39, 8.7, fields.customerAddress ? COLORS.gray500 : '#94a3b8');
    text(field(fields.customerContact, '[Phone / Email]'), MARGIN_X + 10, topBoxY + 51, 8.7, fields.customerContact ? COLORS.gray500 : '#94a3b8');

    const metaX = MARGIN_X + leftW + 11;
    const metaRight = PAGE_W - MARGIN_X - 11;
    const metas = [
      ['Invoice No.', field(fields.invoiceNo, 'INV-0001')],
      ['Invoice Date', dateLabel(fields.invoiceDate)],
    ];
    metas.forEach(([label, value], index) => {
      const rowTop = topBoxY + 13 + (index * 25);
      text(label, metaX, rowTop, 8.2, COLORS.navy, true);
      text(value, metaRight, rowTop, 8.2, COLORS.gray900, false, 'right');
    });

    // Only populated line items are printed. Blank editor rows are ignored.
    const printableItems = getPrintableItems(items);
    const tableY = 187;
    const headerH = 21;
    const rowH = 26;
    const columns = [
      { label: '#', width: 34 },
      { label: 'Description of Products / Services', width: 220 },
      { label: 'Qty', width: 61 },
      { label: 'Unit Price', width: 99 },
      { label: 'Amount', width: CONTENT_W - 34 - 220 - 61 - 99 },
    ];
    let colX = MARGIN_X;
    columns.forEach((column, index) => {
      rect(colX, tableY, column.width, headerH, { fillColor: COLORS.blue, strokeColor: COLORS.white, lineWidth: 0.45 });
      text(column.label, index === 1 ? colX + 7 : colX + (column.width / 2), tableY + 6.3, 7.6, COLORS.white, true, index === 1 ? 'left' : 'center');
      colX += column.width;
    });
    for (let index = 0; index < printableItems.length; index += 1) {
      const item = printableItems[index] || { description: '', quantity: '', unitPrice: '' };
      const rowTop = tableY + headerH + (index * rowH);
      const bg = index % 2 ? COLORS.row : COLORS.white;
      let x = MARGIN_X;
      columns.forEach((column) => {
        rect(x, rowTop, column.width, rowH, { fillColor: bg, strokeColor: COLORS.gray200, lineWidth: 0.45 });
        x += column.width;
      });
      const quantity = numberOrZero(item.quantity);
      const unitPrice = numberOrZero(item.unitPrice);
      const amount = quantity * unitPrice;
      text(String(index + 1), MARGIN_X + 17, rowTop + 8.8, 7.5, COLORS.gray500, false, 'center');
      const description = item.description && String(item.description).trim() ? String(item.description).trim() : '[Item / service description]';
      multilines(description, MARGIN_X + 41, rowTop + 7.2, 206, 7.2, item.description && String(item.description).trim() ? COLORS.gray900 : '#a7afba', 2);
      if (quantity > 0) text(String(item.quantity), MARGIN_X + 34 + 220 + (61 / 2), rowTop + 8.8, 7.5, COLORS.gray500, false, 'center');
      if (unitPrice > 0) text(money(unitPrice, currency), MARGIN_X + 34 + 220 + 61 + 99 - 7, rowTop + 8.8, 7.5, COLORS.gray900, false, 'right');
      if (amount > 0) text(money(amount, currency), PAGE_W - MARGIN_X - 7, rowTop + 8.8, 7.5, COLORS.gray900, false, 'right');
    }

    // Terms and payment summary. Paid amount is deducted from the grand total.
    const summaryY = tableY + headerH + (printableItems.length * rowH) + 15;
    const summaryH = 102;
    const noteW = CONTENT_W * 0.61;
    const totalW = CONTENT_W - noteW;
    rect(MARGIN_X, summaryY, noteW, summaryH, { fillColor: COLORS.lightPurple, strokeColor: '#d8d2ff' });
    text('TERMS & CONDITIONS', MARGIN_X + 9, summaryY + 10, 7.5, COLORS.purple, true);
    multilines(field(fields.notes, DEFAULT_NOTES), MARGIN_X + 9, summaryY + 22, noteW - 18, 6.8, COLORS.navy, 6);
    const totalX = MARGIN_X + noteW;
    const paidInFull = valueTotals.total > 0 && valueTotals.balance <= 0.005;
    const totalRows = [
      ['Subtotal', money(valueTotals.subtotal, currency), 'normal'],
      ['Discount', money(valueTotals.discount, currency), 'normal'],
      ['Tax / VAT', money(valueTotals.tax, currency), 'normal'],
      ['Grand Total', money(valueTotals.total, currency), 'grand'],
      ['Paid Amount', money(valueTotals.paid, currency), 'paid'],
      [paidInFull ? 'PAID IN FULL' : 'BALANCE DUE', money(valueTotals.balance, currency), paidInFull ? 'settled' : 'balance'],
    ];
    const totalRowH = summaryH / totalRows.length;
    totalRows.forEach(([label, value, type], index) => {
      const rowTop = summaryY + (index * totalRowH);
      const isBalance = type === 'balance' || type === 'settled';
      const isPaid = type === 'paid';
      const isGrand = type === 'grand';
      const fillColor = isBalance ? (type === 'settled' ? COLORS.green : COLORS.purple) : (isPaid ? COLORS.lightGreen : COLORS.white);
      const strokeColor = isBalance ? (type === 'settled' ? COLORS.green : COLORS.purple) : (isPaid ? COLORS.greenBorder : COLORS.gray200);
      const color = isBalance ? COLORS.white : (isPaid ? COLORS.green : (isGrand ? COLORS.navy : COLORS.gray500));
      const isBold = isBalance || isPaid || isGrand;
      const fontSize = isBalance ? 8 : 7.35;
      rect(totalX, rowTop, totalW, totalRowH, { fillColor, strokeColor, lineWidth: 0.45 });
      text(label, totalX + 8, rowTop + 5.3, fontSize, color, isBold);
      text(value, totalX + totalW - 8, rowTop + 5.3, fontSize, isBalance ? COLORS.white : (isPaid ? COLORS.green : COLORS.gray900), isBold, 'right');
    });

    // Signature deliberately moved lower, while preserving clear space above the footer.
    const paymentY = Math.max(summaryY + 116, 440);
    text('Payment Method:', MARGIN_X, paymentY + 10, 7.6, COLORS.gray500);
    text(field(fields.paymentMethod, 'Cash / Bank Transfer / Mobile Financial Service'), MARGIN_X + 62, paymentY + 10, 7.6, COLORS.gray700);
    const signX = MARGIN_X + (CONTENT_W * 0.61);
    line(signX, paymentY + 31, PAGE_W - MARGIN_X, paymentY + 31, COLORS.gray500, 0.7);
    text('Authorized Signature', signX + ((PAGE_W - MARGIN_X - signX) / 2), paymentY + 39, 7.7, COLORS.gray500, true, 'center');

    // Footer: one office address plus three aligned contact groups. The website group
    // is mathematically anchored to the same right edge as the invoice header and tables.
    const footerTop = 776;
    const footerLeft = MARGIN_X + 9;
    const footerRight = PAGE_W - MARGIN_X - 9;
    const footerLabelSize = 7.8;
    const footerValueSize = 8.5;
    const footerGap = 6;
    rect(MARGIN_X, footerTop, CONTENT_W, 3.5, { fillColor: COLORS.purple });
    text('OFFICE:', footerLeft, footerTop + 12, 8.0, COLORS.blue, true);
    text('26 Shakhari Nagar Lane, Gendaria, Dhaka, Bangladesh', footerLeft + 42, footerTop + 12, 8.8, COLORS.navy, true);

    function footerGroup(label, value, anchor, align) {
      const labelWidth = textWidth(label, footerLabelSize, true);
      const valueWidth = textWidth(value, footerValueSize, true);
      const groupWidth = labelWidth + footerGap + valueWidth;
      let start = anchor;
      if (align === 'center') start = anchor - (groupWidth / 2);
      if (align === 'right') start = anchor - groupWidth;
      text(label, start, footerTop + 27, footerLabelSize, COLORS.blue, true);
      text(value, start + labelWidth + footerGap, footerTop + 27, footerValueSize, COLORS.navy, true);
    }

    footerGroup('MOBILE:', '01410009901', footerLeft, 'left');
    footerGroup('EMAIL:', 'tscifer@gmail.com', PAGE_W / 2, 'center');
    footerGroup('WEBSITE:', 'scifer.dev', footerRight, 'right');

    return commands.join('\n');
  }

  function createInvoicePdf(draft) {
    return makePdf(buildContent(draft));
  }

  function filenameFromDraft(draft) {
    const raw = ((draft.fields || {}).invoiceNo || 'Scifer_Invoice').trim();
    const safe = raw.replace(/[^a-z0-9_-]+/gi, '_').replace(/^_+|_+$/g, '');
    return `${safe || 'Scifer_Invoice'}.pdf`;
  }

  function downloadInvoicePdf(draft) {
    const blob = new Blob([createInvoicePdf(draft)], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filenameFromDraft(draft);
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1500);
  }

  window.SciferPdfGenerator = { createInvoicePdf, downloadInvoicePdf };
})();
